// n8n Code node (Node.js 18+)
// Entrada esperada: dois itens, um com {message:{text}} e outro com {currentDate}
// Saída: 1 item no formato da tabela raw_inputs do Supabase

const all = items.map(i => i.json);

const rawText = all.find(o => o?.message?.text)?.message.text ?? "";
const capturedAt = all.find(o => o?.currentDate)?.currentDate ?? new Date().toISOString();

// Regex para timestamp estilo "05 Nov 2025 04:29:33" (sem limpar o texto)
const dateRegex = /\b(\d{1,2})\s+(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{4})\s+(\d{2}):(\d{2}):(\d{2})\b/mi;
const m = rawText.match(dateRegex);

let publishedAtText = null;
let publishedAtIso = null;

if (m) {
  publishedAtText = m[0]; // exatamente como está no texto
  const day = parseInt(m[1], 10);
  const mon = m[2].slice(0,3).toLowerCase();
  const year = parseInt(m[3], 10);
  const hh = parseInt(m[4], 10);
  const mm = parseInt(m[5], 10);
  const ss = parseInt(m[6], 10);

  const monthIdx = {
    jan:0,feb:1,mar:2,apr:3,may:4,jun:5,
    jul:6,aug:7,sep:8,oct:9,nov:10,dec:11
  }[mon];

  if (Number.isInteger(monthIdx)) {
    // Interpretado como UTC para padronizar
    const dt = new Date(Date.UTC(year, monthIdx, day, hh, mm, ss));
    publishedAtIso = dt.toISOString();
  }
}

// Monta o registro no formato da tabela raw_inputs
const out = {
  // Remova 'captured_at' se quiser usar o DEFAULT NOW() do banco
  captured_at: capturedAt,          // TIMESTAMPTZ
  processed: false,                 // deixa marcado como ainda não processado
  blob_content: {
    article_text: rawText,          // texto original, sem limpeza
    published_at_text: publishedAtText, // como apareceu no texto (pode ser null)
    published_at_iso: publishedAtIso     // normalizado em UTC (pode ser null)
  }
};

return [{ json: out }];

// n8n Code node (JavaScript)
// Entrada esperada: items[0].json contendo:
//  - { articles: [ { title, fullText, paragraphs, publishDate, ... }, ... ] }
//  - OU um array no topo: [ { articles: [...] } ]
// Saída: um item por artigo com campo .json.text (title + fullText)

function pickArticles(input) {
  if (!input) return [];
  // Caso 1: já seja { articles: [...] }
  if (Array.isArray(input.articles)) return input.articles;

  // Caso 2: seja um array no topo: [ { articles: [...] } ]
  if (Array.isArray(input) && input.length && Array.isArray(input[0]?.articles)) {
    return input[0].articles;
  }

  // Caso 3: já venha um único artigo (title presente)
  if (input.title) return [input];

  return [];
}

const root = items?.[0]?.json;
const articles = pickArticles(root);

if (!articles.length) {
  return [{
    json: {
      error: 'Estrutura de entrada não contém artigos.',
      receivedSample: root
    }
  }];
}

const out = articles.map((a, idx) => {
  const title = (a.title ?? '').toString().trim();
  let body = (a.fullText ?? '').toString().trim();

  if (!body && Array.isArray(a.paragraphs)) {
    body = a.paragraphs.map(p => (p ?? '').toString().trim()).filter(Boolean).join('\n\n');
  }

  const text = [title, body].filter(Boolean).join('\n\n');

  return {
    json: {
      index: idx + 1,
      text,                 // <- texto único para usar no loop
      title,
      publishDate: a.publishDate ?? a.gridDateTime ?? null,
      author: a.author ?? null,
      gridKey: a.gridKey ?? null,
      gridDateTime: a.gridDateTime ?? null,
      extractedAt: a.extractedAt ?? null,
      metadata: a.metadata ?? null,
      // Opcional: manter o objeto original
      // original: a
    }
  };
});

return out;

// Code Node - Adicionar block do Discord em cada notícia
  // IMPORTANTE: Este nó recebe APENAS notícias novas (não duplicadas) do PostgreSQL

  const items = $input.all();
  const output = [];

  // Validar blocks permitidos
  const validBlocks = ['Top News', 'Market Commentary', 'Rationale', 'News', 'General'];

  // Processar cada notícia individualmente
  for (const item of items) {
    const news = item.json;

    // O SQL já tem o block original da notícia
    // E também calculou o discord_channel baseado em:
    // - relevance_score
    // - block (Top News, Market Commentary, Rationale, News)
    // - is_iron_ore_related

    let block = news.block || 'General';

    // Validar se o block existe, senão usa General
    if (!validBlocks.includes(block)) {
      block = 'General';
    }

    // Adicionar cada notícia como item individual com campo block
    output.push({
      json: {
        ...news,
        block: block, // Usando block ao invés de channel
        discord_channel: news.discord_channel, // Mantém o canal calculado pelo SQL
        requires_translation: true,
        requires_summary: true
      }
    });
  }

  // Se não houver notícias novas
  if (output.length === 0) {
    return [{
      json: {
        message: "Nenhuma notícia nova para processar",
        duplicates_filtered: true,
        block: null
      }
    }];
  }

  return output; // Retorna TODOS os items individualmente com campo block

// n8n Code node (JavaScript)
// Entrada esperada em items[0].json (ou [ { ... } ] como no exemplo).
// Saída: um item por artigo, separado entre newsInsights e marketCommentary.

function unwrapRoot(input) {
  if (Array.isArray(input)) return input[0] ?? {};
  return input ?? {};
}

function toStringSafe(v) {
  return (v ?? '').toString().trim();
}

function buildFullText(entry) {
  const ft = toStringSafe(entry.fullText);
  if (ft) return ft;
  if (Array.isArray(entry.paragraphs)) {
    const joined = entry.paragraphs
      .map(p => toStringSafe(p))
      .filter(Boolean)
      .join('\n\n');
    return joined || null;
  }
  return null;
}

function deriveHeadline(entry) {
  const title = toStringSafe(entry.title);
  const dateField = toStringSafe(entry.date);
  const source = toStringSafe(entry.source);

  // Se o título for genérico ("News & Insights" / "Market Commentary"),
  // tentamos usar 'date' quando parecer um cabeçalho textual (market commentary costuma vir assim).
  const isGeneric =
    /^news\s*&\s*insights$/i.test(title) || /^market\s*commentary$/i.test(title);

  // Heurística: se 'date' não parecer data/tempo ("11/05/2025 ..." ou "14 hours ago"), tratamos como headline.
  const looksLikeDate =
    /^\d{2}\/\d{2}\/\d{4}\s+\d{2}:\d{2}:\d{2}\s+UTC$/i.test(dateField) ||
    /^\d+\s+\w+\s+ago$/i.test(dateField);

  if (title && !isGeneric) return title;
  if (dateField && !looksLikeDate) return dateField;
  // fallback
  return title || dateField || null;
}

const rootIn = unwrapRoot(items?.[0]?.json);
const out = [];

// Helper para empurrar um array (newsInsights / marketCommentary)
function pushGroup(arr, category) {
  if (!Array.isArray(arr)) return;
  for (const entry of arr) {
    const fullText = buildFullText(entry);
    const extractedAt = entry.extractedAt ?? rootIn.extractedAt ?? null;

    out.push({
      json: {
        category,                                 // 'newsInsights' | 'marketCommentary'
        index: entry.index ?? null,
        headline: deriveHeadline(entry),          // título legível
        fullText,                                 // conteúdo completo (ou paragraphs unidos)
        extractedAt,                              // timestamp de extração
        // metadados úteis
        titleOriginal: toStringSafe(entry.title) || null,
        author: entry.author ?? null,
        source: entry.source ?? null,
        publishDate: entry.publishDate ?? null,
        date: entry.date ?? null,
        elementId: entry.elementId ?? null,
      },
    });
  }
}

pushGroup(rootIn.newsInsights, 'newsInsights');
pushGroup(rootIn.marketCommentary, 'marketCommentary');

if (!out.length) {
  return [{
    json: {
      error: 'Nenhum item encontrado em newsInsights ou marketCommentary.',
      receivedKeys: Object.keys(rootIn || {})
    }
  }];
}

return out;

// Pega a data de entrada
const inputDate = new Date($input.item.json.currentDate);

// Início do dia em UTC (00:00:00)
const startOfDay = new Date(inputDate);
startOfDay.setUTCHours(0, 0, 0, 0);

// Fim do dia em UTC (23:59:59.999)
const endOfDay = new Date(inputDate);
endOfDay.setUTCHours(23, 59, 59, 999);

return {
  json: {
    dateStart: startOfDay.toISOString(),
    dateEnd: endOfDay.toISOString()
  }
};

