// FUNÇÃO: Sanitiza strings com caracteres problemáticos
function sanitizeJsonString(str) {
  if (!str) return str;

  // 1. Substituir smart quotes por aspas normais
  str = str
    .replace(/[\u201C\u201D\u201E\u201F\u2033\u2036]/g, '"')  // Smart double quotes
    .replace(/[\u2018\u2019\u201A\u201B\u2032\u2035]/g, "'")  // Smart single quotes
    .replace(/[\u00AB\u00BB]/g, '"')  // Guillemets
    .replace(/[\u2014\u2013]/g, '-')  // Em dash, en dash
    .replace(/\u2026/g, '...')  // Ellipsis
    .replace(/\u00A0/g, ' ');  // Non-breaking space

  // 2. Remover caracteres de controle
  str = str.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');

  return str;
}

// FUNÇÃO: Extrai JSON do output do AI Agent
function extractJsonFromOutput(output) {
  if (!output) {
    throw new Error('Output do AI Agent está vazio');
  }

  // 1. Sanitizar primeiro (smart quotes, etc)
  let cleaned = sanitizeJsonString(output);

  // 2. Remover markdown code blocks
  cleaned = cleaned
    .replace(/^```json\s*\n?/gi, '')
    .replace(/^```\s*\n?/gi, '')
    .replace(/\n?```\s*$/gi, '')
    .trim();

  // 3. Encontrar o JSON se não começa com { ou [
  if (!cleaned.startsWith('{') && !cleaned.startsWith('[')) {
    const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      cleaned = jsonMatch[0];
    } else {
      throw new Error('Não foi possível encontrar JSON válido no output');
    }
  }

  // 4. Primeira tentativa de parse
  try {
    return JSON.parse(cleaned);
  } catch (firstError) {
    console.log('Primeira tentativa falhou:', firstError.message);
  }

  // 5. Tentar corrigir newlines não escapados dentro de strings
  let fixedJson = cleaned;
  for (let i = 0; i < 5; i++) {
    fixedJson = fixedJson.replace(/"([^"]*?)\n([^"]*?)"/g, function(match, p1, p2) {
      return '"' + p1 + '\\n' + p2 + '"';
    });
  }

  // 6. Segunda tentativa
  try {
    console.log('Parse bem sucedido após correção de newlines');
    return JSON.parse(fixedJson);
  } catch (secondError) {
    console.log('Segunda tentativa falhou:', secondError.message);
  }

  // 7. Última tentativa: remover todas as quebras de linha
  let lastResort = cleaned
    .replace(/\r\n/g, ' ')
    .replace(/\n/g, ' ')
    .replace(/\r/g, ' ')
    .replace(/\t/g, ' ')
    .replace(/\s+/g, ' ');

  try {
    console.log('Parse bem sucedido após remover quebras de linha');
    return JSON.parse(lastResort);
  } catch (finalError) {
    console.error('Todas as tentativas falharam');
    console.error('Erro final:', finalError.message);
    throw new Error('Falha ao fazer parse do JSON: ' + finalError.message);
  }
}

// PROCESSAMENTO PRINCIPAL
const agentOutput = $json.output;

let result;
try {
  result = extractJsonFromOutput(agentOutput);
} catch (error) {
  throw new Error('Erro ao fazer parse do JSON: ' + error.message);
}

// Adiciona o raw_id (do node anterior que buscou da raw_inputs)
result.raw_id = $('Edit Fields3').first().json.id;

// Adiciona timestamp
result.created_at = new Date().toISOString();

// Remove campos null ou vazios para economizar espaço
Object.keys(result).forEach(function(key) {
  if (result[key] === null || result[key] === '') {
    delete result[key];
  }
  // Remove arrays vazios também
  if (Array.isArray(result[key]) && result[key].length === 0) {
    delete result[key];
  }
  // Remove objetos vazios
  if (typeof result[key] === 'object' && !Array.isArray(result[key]) && result[key] !== null && Object.keys(result[key]).length === 0) {
    delete result[key];
  }
});

// Validações importantes
if (!result.tier) {
  throw new Error('Tier é obrigatório');
}

if (!result.category) {
  throw new Error('Category é obrigatório');
}

// Ajusta o original_content para não exceder limite (se necessário)
if (result.original_content && result.original_content.length > 1000) {
  result.original_content = result.original_content.substring(0, 997) + '...';
}

// Retorna o objeto limpo e pronto para inserir
return result;
